import { useSnackbar } from 'notistack'
import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router'

import { Box, Button, Grid, MenuItem, Stack, TextField, Typography } from '@mui/material'

import {
  PARTNER_COUPON_MESSAGES,
  PARTNER_COUPON_STATUS_LABELS,
  PARTNER_COUPON_UNLOCK_TYPE_LABELS,
  PARTNER_COUPON_USAGE_TYPE_LABELS
} from 'src/data/partnerBenefits'

import { getDateInputValueFromString, getEndOfDayIsoString, getStartOfDayIsoString } from 'src/utils/partnerBenefits'

import type {
  PartnerCoupon,
  PartnerCouponPayload,
  PartnerCouponStatus,
  PartnerCouponUnlockType,
  PartnerCouponUsageType,
  PartnerStore
} from 'src/models/partnerBenefit'

interface PartnerCouponFormValues {
  partnerStoreId: string
  benefitContent: string
  startDate: string
  endDate: string
  audience: string
  howToUse: string
  verificationMethod: string
  notice: string
  usageType: PartnerCouponUsageType
  unlockType: PartnerCouponUnlockType
  status: PartnerCouponStatus
}

interface PartnerCouponFormProps {
  stores: PartnerStore[]
  editingCoupon?: PartnerCoupon
  onCreatePartnerCoupon: (coupon: PartnerCouponPayload) => Promise<unknown>
  onUpdatePartnerCoupon: (couponId: number, coupon: PartnerCouponPayload) => Promise<unknown>
}

const getEmptyPartnerCouponFormValues = (firstStoreId = ''): PartnerCouponFormValues => ({
  partnerStoreId: firstStoreId,
  benefitContent: '',
  startDate: '2026-04-20',
  endDate: '2026-05-20',
  audience: 'KLUB 인증 동아리 회원',
  howToUse: '결제 전에 KLUB에서 쿠폰을 열고 직원에게 제시해주세요.',
  verificationMethod: 'KLUB 로그인 및 동아리 소속 인증 화면 확인',
  notice: '타 할인과 중복 사용이 어려울 수 있으며, 사용 후 즉시 소진 처리됩니다.',
  usageType: 'ONE_TIME',
  unlockType: 'INSTANT',
  status: 'ACTIVE'
})

const getPartnerCouponFormValues = (coupon: PartnerCoupon | undefined, firstStoreId = ''): PartnerCouponFormValues => {
  if (!coupon) return getEmptyPartnerCouponFormValues(firstStoreId)

  return {
    partnerStoreId: `${coupon.partnerStoreId}`,
    benefitContent: coupon.benefitContent,
    startDate: getDateInputValueFromString(coupon.startDate),
    endDate: getDateInputValueFromString(coupon.endDate),
    audience: coupon.audience,
    howToUse: coupon.howToUse,
    verificationMethod: coupon.verificationMethod,
    notice: coupon.notice,
    usageType: coupon.usageType,
    unlockType: coupon.unlockType,
    status: coupon.status ?? 'ACTIVE'
  }
}

const getPartnerCouponPayload = (couponFormValues: PartnerCouponFormValues): PartnerCouponPayload => ({
  partnerStoreId: Number(couponFormValues.partnerStoreId),
  benefitContent: couponFormValues.benefitContent.trim(),
  startDate: getStartOfDayIsoString(couponFormValues.startDate),
  endDate: getEndOfDayIsoString(couponFormValues.endDate),
  audience: couponFormValues.audience.trim(),
  howToUse: couponFormValues.howToUse.trim(),
  verificationMethod: couponFormValues.verificationMethod.trim(),
  notice: couponFormValues.notice.trim(),
  usageType: couponFormValues.usageType,
  unlockType: couponFormValues.unlockType,
  status: couponFormValues.status
})

const PartnerCouponForm: React.FC<PartnerCouponFormProps> = ({
  stores,
  editingCoupon,
  onCreatePartnerCoupon,
  onUpdatePartnerCoupon
}) => {
  const navigate = useNavigate()
  const { enqueueSnackbar } = useSnackbar()
  const activeStores = stores.filter(store => !store.deletedAt)
  const firstStoreId = activeStores[0] ? `${activeStores[0].id}` : ''
  const [couponFormValues, setCouponFormValues] = useState<PartnerCouponFormValues>(() =>
    getPartnerCouponFormValues(editingCoupon, firstStoreId)
  )
  const [isSubmitting, setIsSubmitting] = useState(false)
  const isEditing = !!editingCoupon

  useEffect(() => {
    setCouponFormValues(getPartnerCouponFormValues(editingCoupon, firstStoreId))
  }, [editingCoupon, firstStoreId])

  const handleCouponTextFieldChange: React.ChangeEventHandler<HTMLInputElement> = event => {
    const { name, value } = event.target
    setCouponFormValues(prevCouponFormValues => ({ ...prevCouponFormValues, [name]: value }))
  }

  const handleCouponFormSubmitClick: React.MouseEventHandler<HTMLButtonElement> = async () => {
    if (activeStores.length === 0) {
      enqueueSnackbar(PARTNER_COUPON_MESSAGES.NO_STORE_FOR_COUPON, { variant: 'warning' })
      return
    }

    if (
      !couponFormValues.partnerStoreId ||
      !couponFormValues.benefitContent.trim() ||
      !couponFormValues.startDate ||
      !couponFormValues.endDate ||
      !couponFormValues.audience.trim() ||
      !couponFormValues.howToUse.trim() ||
      !couponFormValues.verificationMethod.trim() ||
      !couponFormValues.notice.trim()
    ) {
      enqueueSnackbar(PARTNER_COUPON_MESSAGES.COUPON_REQUIRE, { variant: 'warning' })
      return
    }

    if (couponFormValues.endDate < couponFormValues.startDate) {
      enqueueSnackbar(PARTNER_COUPON_MESSAGES.WRONG_DATE, { variant: 'warning' })
      return
    }

    const couponPayload = getPartnerCouponPayload(couponFormValues)

    try {
      setIsSubmitting(true)
      if (editingCoupon) {
        await onUpdatePartnerCoupon(editingCoupon.id, couponPayload)
        enqueueSnackbar(PARTNER_COUPON_MESSAGES.UPDATE_COUPON_SUCCESS, { variant: 'success' })
        navigate('/admin/benefit-coupons')
        return
      }

      await onCreatePartnerCoupon(couponPayload)
      enqueueSnackbar(PARTNER_COUPON_MESSAGES.ADD_COUPON_SUCCESS, { variant: 'success' })
      setCouponFormValues(getEmptyPartnerCouponFormValues(firstStoreId))
    } catch {
      return
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleCouponEditCancelButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin/benefit-coupons')
  }

  return (
    <Box>
      <Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" spacing={2} sx={{ mb: 3 }}>
        <Box>
          <Typography variant="h4">{isEditing ? '쿠폰 수정' : '쿠폰 등록'}</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
            연결 가게, 기간, 사용 조건, 잠금 방식과 public 화면에 표시될 안내 정보를 입력합니다.
          </Typography>
        </Box>
        <Button variant="outlined" href="/admin/benefit-coupons">
          등록된 쿠폰 관리 보기
        </Button>
      </Stack>
      <Grid container spacing={2}>
        <Grid item xs={12} md={6}>
          <TextField
            select
            fullWidth
            label="연결할 가게"
            name="partnerStoreId"
            value={couponFormValues.partnerStoreId}
            onChange={handleCouponTextFieldChange}
            disabled={activeStores.length === 0}
          >
            {activeStores.map(store => (
              <MenuItem key={store.id} value={`${store.id}`}>
                {store.name}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={12} md={3}>
          <TextField
            fullWidth
            label="쿠폰 시작일"
            name="startDate"
            type="date"
            value={couponFormValues.startDate}
            onChange={handleCouponTextFieldChange}
            InputLabelProps={{ shrink: true }}
          />
        </Grid>
        <Grid item xs={12} md={3}>
          <TextField
            fullWidth
            label="쿠폰 종료일"
            name="endDate"
            type="date"
            value={couponFormValues.endDate}
            onChange={handleCouponTextFieldChange}
            InputLabelProps={{ shrink: true }}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            fullWidth
            label="혜택 문구"
            name="benefitContent"
            value={couponFormValues.benefitContent}
            onChange={handleCouponTextFieldChange}
          />
        </Grid>
        <Grid item xs={12} md={4}>
          <TextField
            select
            fullWidth
            label="사용 형태"
            name="usageType"
            value={couponFormValues.usageType}
            onChange={handleCouponTextFieldChange}
          >
            {Object.entries(PARTNER_COUPON_USAGE_TYPE_LABELS).map(([value, label]) => (
              <MenuItem key={value} value={value}>
                {label}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={12} md={4}>
          <TextField
            select
            fullWidth
            label="활성 상태"
            name="status"
            value={couponFormValues.status}
            onChange={handleCouponTextFieldChange}
          >
            {Object.entries(PARTNER_COUPON_STATUS_LABELS).map(([value, label]) => (
              <MenuItem key={value} value={value}>
                {label}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={12} md={4}>
          <TextField
            select
            fullWidth
            label="잠금 해제 방식"
            name="unlockType"
            value={couponFormValues.unlockType}
            onChange={handleCouponTextFieldChange}
          >
            {Object.entries(PARTNER_COUPON_UNLOCK_TYPE_LABELS).map(([value, label]) => (
              <MenuItem key={value} value={value}>
                {label}
              </MenuItem>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={12}>
          <TextField
            fullWidth
            label="사용 대상"
            name="audience"
            value={couponFormValues.audience}
            onChange={handleCouponTextFieldChange}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            fullWidth
            multiline
            minRows={2}
            label="사용 방법"
            name="howToUse"
            value={couponFormValues.howToUse}
            onChange={handleCouponTextFieldChange}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            fullWidth
            label="인증 방식"
            name="verificationMethod"
            value={couponFormValues.verificationMethod}
            onChange={handleCouponTextFieldChange}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            fullWidth
            multiline
            minRows={2}
            label="유의사항"
            name="notice"
            value={couponFormValues.notice}
            onChange={handleCouponTextFieldChange}
          />
        </Grid>
        <Grid item xs={12}>
          <Stack direction="row" spacing={1.5} justifyContent="flex-end">
            {isEditing && (
              <Button variant="outlined" color="secondary" onClick={handleCouponEditCancelButtonClick}>
                수정 취소
              </Button>
            )}
            <Button variant="contained" color="success" onClick={handleCouponFormSubmitClick} disabled={isSubmitting}>
              {isEditing ? '쿠폰 수정' : '쿠폰 등록'}
            </Button>
          </Stack>
        </Grid>
      </Grid>
    </Box>
  )
}

export default PartnerCouponForm
