import { Helmet } from 'react-helmet-async'
import { useNavigate } from 'react-router'
import { useSearchParams } from 'react-router-dom'

import {
  Box,
  Button,
  Card,
  CircularProgress,
  Container,
  Stack,
  Typography,
  useMediaQuery,
  useTheme
} from '@mui/material'

import PageTitleWrapper from 'src/components/PageTitleWrapper'

import PartnerCouponForm from 'src/content/users/admin/PartnerCouponForm'

import { usePartnerBenefits } from 'src/hooks/usePartnerBenefits'

const BenefitCouponFormPage: React.FC = () => {
  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'))
  const navigate = useNavigate()
  const [searchParams] = useSearchParams()
  const { stores, coupons, createPartnerCoupon, updatePartnerCoupon, isLoading, isFetching } = usePartnerBenefits({
    mode: 'admin'
  })
  const benefitCouponIdParam = searchParams.get('benefitCouponId')
  const benefitCouponId = benefitCouponIdParam ? Number(benefitCouponIdParam) : null
  const isEditMode = benefitCouponId !== null
  const editingCoupon = benefitCouponId
    ? coupons.find(coupon => coupon.id === benefitCouponId && !coupon.deletedAt)
    : undefined
  const isWaitingForEditingCoupon = isEditMode && !editingCoupon && (isLoading || isFetching)

  const handleAdminButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin')
  }

  const handleCouponManageButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin/benefit-coupons')
  }

  return (
    <>
      <Helmet>
        <title>{isEditMode ? '쿠폰 수정' : '쿠폰 등록'} - KLUB</title>
      </Helmet>
      <PageTitleWrapper>
        <Stack direction={{ xs: 'column', md: 'row' }} justifyContent="space-between" spacing={2}>
          <Box>
            <Typography variant={isMobile ? 'h4' : 'h3'}>{isEditMode ? '쿠폰 수정' : '쿠폰 등록'}</Typography>
            <Typography color="text.secondary" sx={{ mt: 1 }}>
              연결 가게, 기간, 사용 조건, 잠금 방식을 입력합니다.
            </Typography>
          </Box>
          <Button variant="outlined" onClick={handleAdminButtonClick}>
            어드민 페이지
          </Button>
        </Stack>
      </PageTitleWrapper>
      <Container maxWidth="lg">
        <Card sx={{ p: { xs: 2, md: 3 }, boxShadow: theme.header.boxShadow }}>
          {isWaitingForEditingCoupon ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
              <CircularProgress />
            </Box>
          ) : isEditMode && !editingCoupon ? (
            <Stack alignItems="center" spacing={2} sx={{ py: 4 }}>
              <Typography variant="h4">수정할 쿠폰을 찾을 수 없습니다.</Typography>
              <Button variant="outlined" onClick={handleCouponManageButtonClick}>
                등록된 쿠폰 관리 보기
              </Button>
            </Stack>
          ) : (
            <PartnerCouponForm
              stores={stores}
              editingCoupon={editingCoupon}
              onCreatePartnerCoupon={createPartnerCoupon}
              onUpdatePartnerCoupon={updatePartnerCoupon}
            />
          )}
        </Card>
      </Container>
    </>
  )
}

export default BenefitCouponFormPage
